// Fibonacci sequence calculator

int fibonacci(int n) {
    if (n <= 1) {
        return n;
    }
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int i = 0;
    while (i < 15) {
        int fib = fibonacci(i);
        print(fib);
        i++;
    }
    return 0;
}

