sensor_read:
// Read analog sensor and display via serial
#define SENSOR_PIN 34
#define LED_PIN 2
#define OUTPUT 1
#define THRESHOLD 2000

int main() {
    serialBegin(115200);
    pinMode(LED_PIN, OUTPUT);

    int count = 0;
    while (count < 20) {
        int value = analogRead(SENSOR_PIN);

        serialPrint("Sensor: ");
        serialPrintInt(value);
        serialPrintln("");

        if (value > THRESHOLD) {
            digitalWrite(LED_PIN, 1);
        } else {
            digitalWrite(LED_PIN, 0);
        }

        delay(100);
        count++;
    }
    return 0;
}

sort:
// Bubble sort an array of integers

int main() {
    int arr[10] = {64, 34, 25, 12, 22, 11, 90, 1, 55, 42};
    int n = 10;

    // Print original
    printStr("Before sort:");
    int k = 0;
    while (k < n) {
        print(arr[k]);
        k++;
    }

    // Bubble sort
    int i = 0;
    while (i < n - 1) {
        int j = 0;
        while (j < n - i - 1) {
            if (arr[j] > arr[j + 1]) {
                // Swap
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
            j++;
        }
        i++;
    }

    // Print sorted
    printStr("After sort:");
    k = 0;
    while (k < n) {
        print(arr[k]);
        k++;
    }

    return 0;
}

file_io:
// File I/O demo — write and read back
// On ESP32: uses LittleFS, in browser: simulated virtual filesystem

int main() {
    char data[64];
    char buf[64];

    // Prepare data to write
    strcpy(data, "Hello from TinyC!\n");

    // Write to file
    int f = fileOpen("/test.txt", 1);  // 1 = write
    if (f >= 0) {
        fileWrite(f, data, strlen(data));
        fileClose(f);
        printStr("Written OK\n");
    }

    // Read back
    f = fileOpen("/test.txt", 0);  // 0 = read
    if (f >= 0) {
        int n = fileRead(f, buf, 63);
        buf[n] = 0;  // null-terminate
        fileClose(f);
        printStr("Read back: ");
        printString(buf);
    }

    // Check file info
    if (fileExists("/test.txt")) {
        printStr("File size: ");
        print(fileSize("/test.txt"));
        printStr("\n");
    }

    // Clean up
    fileDelete("/test.txt");
    printStr("File deleted\n");

    return 0;
}

