chart:
// Google Line Chart — 1000 data points stored in array
// Demonstrates: heap arrays, WebPage, WebCall, webSend, webFlush, random()
// WebPage draws the chart once, EverySecond shifts new data in
// WebCall shows a sensor-style status row (refreshed periodically)

#define N 1000

int data[N];       // ring buffer of sensor values (heap-allocated, >255)
int pos = 0;       // write position (ring buffer head)
int counter = 0;

// Simple integer sine approximation (x in 0..399 period, returns -100..100)
int isin(int x) {
    int p = x % 400;
    if (p < 0) p = p + 400;
    if (p < 100) return p;
    if (p < 200) return 200 - p;
    if (p < 300) return -(p - 200);
    return -(400 - p);
}

void EverySecond() {
    // Add a new data point each second (sine + noise)
    int s = isin(counter);
    int noise = random(-15, 15);
    data[pos] = s + noise;
    pos++;
    if (pos >= N) pos = 0;
    counter++;
}

void WebPage() {
    // Called once when page is drawn (FUNC_WEB_ADD_MAIN_BUTTON)
    // Perfect for charts, custom HTML, scripts that should load once
    char buf[128];
    int i;

    // ── Chart container and Google Charts loader ──
    webSend("<div id=\"tc_chart\" style=\"width:100%;height:400px;\"></div>");
    webSend("<script src=\"https://www.gstatic.com/charts/loader.js\"></script>");
    webSend("<script>");
    webSend("google.charts.load('current',{packages:['corechart']});");
    webSend("google.charts.setOnLoadCallback(function(){");
    webSend("var d=new google.visualization.DataTable();");
    webSend("d.addColumn('number','X');");
    webSend("d.addColumn('number','Value');");
    webSend("d.addColumn('number','Avg');");
    webSend("d.addRows([");
    webFlush();

    // ── Output all 1000 data points from ring buffer ──
    int avg = 0;
    i = 0;
    while (i < N) {
        // Read from ring buffer: oldest first
        int idx = pos + i;
        if (idx >= N) idx = idx - N;
        int val = data[idx];

        // Running average (smoothing filter)
        avg = (avg * 9 + val * 10) / 10;
        int smooth = avg / 10;

        // Format: [x, value, avg],
        sprintf(buf, "[%d,", i);
        sprintfAppend(buf, "%d,", val);
        sprintfAppend(buf, "%d]", smooth);
        if (i < N - 1) {
            strcat(buf, ",");
        }
        webSend(buf);

        // Flush every 100 rows to keep buffer manageable
        if (i % 100 == 99) {
            webFlush();
        }
        i++;
    }

    // ── Chart options and render ──
    webSend("]);");
    webSend("var o={title:'TinyC Live Data (1000 pts)',");
    webSend("curveType:'none',legend:{position:'bottom'},");
    webSend("hAxis:{title:'Sample'},vAxis:{title:'Value'},");
    webSend("chartArea:{width:'80%',height:'70%'},");
    webSend("series:{0:{lineWidth:1,color:'#89b4fa'},");
    webSend("1:{lineWidth:2,color:'#f38ba8'}}};");
    webSend("var c=new google.visualization.LineChart(");
    webSend("document.getElementById('tc_chart'));");
    webSend("c.draw(d,o);});");
    webSend("</script>");
    webFlush();
}

void WebCall() {
    // Called periodically for sensor display (FUNC_WEB_SENSOR)
    // Shows a status row that auto-refreshes
    char buf[64];
    sprintf(buf, "{s}TinyC Chart{m}%d samples{e}", counter);
    webSend(buf);
}

void JsonCall() {
    char buf[64];
    sprintf(buf, ",\"TinyC\":{\"Samples\":%d}", counter);
    responseAppend(buf);
}

int main() {
    // Fill array with initial data
    int i = 0;
    while (i < N) {
        data[i] = isin(i) + random(-15, 15);
        i++;
    }
    pos = 0;
    counter = 0;
    printStr("Chart demo active\n");
    printStr("Open Tasmota web page to see the chart\n");
    return 0;
}

udp:
// UDP multicast — share float variables between devices
// Compatible with Tasmota Scripter protocol (239.255.255.250:1999)
// Demonstrates: single float + float array send/receive via global vars

float temperature = 0.0;
int counter = 0;

// Global arrays for UDP send and receive
float sensors[4];      // local sensor data — sent every second
float remote_data[4];  // received from other device
int remote_count = 0;  // how many floats received

void EverySecond() {
    counter++;
    temperature = 20.0 + sin(counter) * 5.0;

    // Broadcast single float
    udpSend("temperature", temperature);

    // Update sensor array and broadcast as float array
    sensors[0] = temperature;
    sensors[1] = 30.0 + cos(counter) * 3.0;
    sensors[2] = (float)(counter % 100);
    sensors[3] = 1013.25;
    udpSendArray("sensors", sensors, 4);
}

void UdpCall() {
    char buf[64];

    // Read single float by name
    float temp = udpRecv("temperature");
    sprintf(buf, "UDP rx: temperature = %.1f\n", temp);
    printString(buf);

    // Read float array into global array
    remote_count = udpRecvArray("sensors", remote_data, 4);
    if (remote_count > 0) {
        sprintf(buf, "UDP rx: %d floats:", remote_count);
        printString(buf);
        int i = 0;
        while (i < remote_count) {
            sprintf(buf, " %.1f", remote_data[i]);
            printString(buf);
            i++;
        }
        printStr("\n");
    }
}

void WebCall() {
    char buf[64];

    // Show local temperature
    sprintf(buf, "{s}Temperature{m}%.1f °C{e}", temperature);
    webSend(buf);

    // Show received remote temperature
    float remote = udpRecv("temperature");
    sprintf(buf, "{s}Remote Temp{m}%.1f °C{e}", remote);
    webSend(buf);

    // Show received array values
    if (remote_count > 0) {
        int i = 0;
        while (i < remote_count) {
            sprintf(buf, "{s}Remote[%d]{m}", i);
            webSend(buf);
            sprintf(buf, "%.1f{e}", remote_data[i]);
            webSend(buf);
            i++;
        }
    }
}

void JsonCall() {
    char buf[64];
    sprintf(buf, ",\"TinyC\":{\"Temp\":%.1f}", temperature);
    responseAppend(buf);
}

int main() {
    remote_count = 0;
    printStr("UDP multicast demo active\n");
    printStr("Sending temperature + array every second\n");
    return 0;
}

sht31:
// SHT31 Temperature & Humidity Sensor Driver
// I2C address 0x44 (or 0x45 if ADDR pin high), bus 0
// Demonstrates: i2cExists, i2cWrite, i2cRead, WebCall, JsonCall

#define SHT31_ADDR  0x44
#define I2C_BUS     0

float sht_temp = 0.0;
float sht_humi = 0.0;
int sht_ok = 0;

// Shared buffer for I2C data (global so CRC function can access it)
char sht_data[6];

// CRC-8 for SHT31 (polynomial 0x31)
// Computes over sht_data[start..start+len-1]
int sht_crc8(int start, int len) {
    int crc = 0xFF;
    int i = 0;
    while (i < len) {
        crc = crc ^ sht_data[start + i];
        int bit = 0;
        while (bit < 8) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc = crc << 1;
            }
            crc = crc & 0xFF;
            bit++;
        }
        i++;
    }
    return crc;
}

void EverySecond() {
    if (!i2cExists(SHT31_ADDR, I2C_BUS)) {
        sht_ok = 0;
        return;
    }

    // Send measurement command: clock stretching, high repeatability
    // Command 0x2C06 — sent as register 0x2C, value 0x06
    if (!i2cWrite8(SHT31_ADDR, 0x2C, 0x06, I2C_BUS)) {
        sht_ok = 0;
        return;
    }

    // SHT31 needs ~15ms for high repeatability measurement
    delay(30);

    // Read 6 bytes without register: [temp_msb, temp_lsb, temp_crc, humi_msb, humi_lsb, humi_crc]
    if (!i2cRead0(SHT31_ADDR, sht_data, 6, I2C_BUS)) {
        sht_ok = 0;
        return;
    }

    // Verify CRC for temperature (bytes 0-1, CRC in byte 2)
    if (sht_crc8(0, 2) != sht_data[2]) {
        sht_ok = 0;
        return;
    }

    // Verify CRC for humidity (bytes 3-4, CRC in byte 5)
    if (sht_crc8(3, 2) != sht_data[5]) {
        sht_ok = 0;
        return;
    }

    // Convert raw values
    // Temperature: -45 + 175 * raw / 65535
    int raw_t = (sht_data[0] << 8) | sht_data[1];
    sht_temp = -45.0 + 175.0 * (float)raw_t / 65535.0;

    // Humidity: 100 * raw / 65535
    int raw_h = (sht_data[3] << 8) | sht_data[4];
    sht_humi = 100.0 * (float)raw_h / 65535.0;

    sht_ok = 1;
}

void WebCall() {
    char buf[64];
    if (sht_ok) {
        sprintf(buf, "{s}SHT31 Temp{m}%.1f °C{e}", sht_temp);
        webSend(buf);
        sprintf(buf, "{s}SHT31 Humidity{m}%.1f %%{e}", sht_humi);
        webSend(buf);
    } else {
        webSend("{s}SHT31{m}not found{e}");
    }
}

void JsonCall() {
    if (!sht_ok) return;
    char buf[96];
    sprintf(buf, ",\"SHT31\":{\"Temperature\":%.1f", sht_temp);
    responseAppend(buf);
    sprintf(buf, ",\"Humidity\":%.1f}", sht_humi);
    responseAppend(buf);
}

int main() {
    sht_ok = 0;
    sht_temp = 0.0;
    sht_humi = 0.0;
    if (i2cExists(SHT31_ADDR, I2C_BUS)) {
        printStr("SHT31 found on bus 0\n");
    } else {
        printStr("SHT31 not found!\n");
    }
    return 0;
}

max31855:
// MAX31855 Thermocouple Sensor Driver (SPI)
// Reads 14-bit thermocouple temperature via SPI
// Demonstrates: spiInit, spiSetCS, spiTransfer, WebCall, JsonCall

#define CS_PIN   5
#define SPI_MHZ  4

float tc_temp = 0.0;
int tc_ok = 0;
int tc_fault = 0;

void EverySecond() {
    // Read 4 bytes from MAX31855 (read-only device, MOSI not needed)
    char buf[4];
    buf[0] = 0;
    buf[1] = 0;
    buf[2] = 0;
    buf[3] = 0;
    int n = spiTransfer(1, buf, 4, 1);
    if (n != 4) {
        tc_ok = 0;
        return;
    }

    // Check fault bit (bit 16 = buf[1] bit 0)
    if (buf[1] & 0x01) {
        tc_fault = buf[3] & 0x07;  // fault code in lowest 3 bits of byte 3
        tc_ok = 0;
        return;
    }

    // Thermocouple temp: bits 31..18 = 14-bit signed value in buf[0..1]
    // buf[0] = bits 31..24, buf[1] = bits 23..16
    int raw = ((buf[0] << 8) | buf[1]) >> 2;  // shift out bits 17..16
    if (raw & 0x2000) {
        raw = raw - 16384;  // sign extend 14-bit to int
    }
    tc_temp = (float)raw * 0.25;
    tc_ok = 1;
    tc_fault = 0;
}

void WebCall() {
    char out[64];
    if (tc_ok) {
        sprintf(out, "{s}MAX31855 Temp{m}%.1f °C{e}", tc_temp);
        webSend(out);
    } else if (tc_fault) {
        sprintf(out, "{s}MAX31855{m}Fault 0x%02X{e}", tc_fault);
        webSend(out);
    } else {
        webSend("{s}MAX31855{m}no data{e}");
    }
}

void JsonCall() {
    if (!tc_ok) return;
    char out[64];
    sprintf(out, ",\"MAX31855\":{\"Temperature\":%.1f}", tc_temp);
    responseAppend(out);
}

int main() {
    // Init hardware SPI at 4 MHz (read-only, no MOSI needed)
    spiInit(-1, -1, -1, SPI_MHZ);
    spiSetCS(1, CS_PIN);

    tc_ok = 0;
    tc_fault = 0;
    tc_temp = 0.0;
    printStr("MAX31855 thermocouple driver ready\n");
    return 0;
}

benchmark:
// TinyC VM Benchmark
// Measures execution speed of various operations
// Reports results via WebCall/JsonCall and serial output

int t_start = 0;
int t_int = 0;
int t_float = 0;
int t_array = 0;
int t_call = 0;
int t_string = 0;
int t_total = 0;

// ── Integer arithmetic benchmark ──
int bench_int() {
    int sum = 0;
    int i = 0;
    while (i < 100000) {
        sum = sum + i;
        sum = sum - (i / 2);
        sum = sum * 3;
        sum = sum / 4;
        sum = sum % 1000000;
        i++;
    }
    return sum;
}

// ── Float arithmetic benchmark ──
float bench_float() {
    float sum = 0.0;
    float x = 1.0;
    int i = 0;
    while (i < 50000) {
        sum = sum + x;
        x = x * 1.0001;
        sum = sum - x * 0.5;
        sum = sum * 1.001;
        sum = sum / 1.001;
        i++;
    }
    return sum;
}

// ── Array access benchmark ──
int bench_array() {
    int arr[200];
    int i = 0;
    // Fill
    while (i < 200) {
        arr[i] = i * 7;
        i++;
    }
    // Random-ish access pattern
    int sum = 0;
    i = 0;
    while (i < 100000) {
        int idx = (i * 31 + 17) % 200;
        sum = sum + arr[idx];
        arr[idx] = sum & 0xFFFF;
        i++;
    }
    return sum;
}

// ── Function call benchmark ──
int add3(int a, int b, int c) {
    return a + b + c;
}

int bench_call() {
    int sum = 0;
    int i = 0;
    while (i < 100000) {
        sum = add3(sum, i, 1);
        sum = sum & 0x7FFFFFFF;
        i++;
    }
    return sum;
}

// ── String operations benchmark ──
int bench_string() {
    char a[32];
    char b[32];
    char c[80];
    int i = 0;
    while (i < 10000) {
        strcpy(a, "Hello");
        strcpy(b, "World");
        strcpy(c, a);
        strcat(c, " ");
        strcat(c, b);
        int len = strlen(c);
        i++;
    }
    return i;
}

void WebCall() {
    char buf[64];
    sprintf(buf, "{s}Benchmark{m}%d ms total{e}", t_total);
    webSend(buf);
    sprintf(buf, "{s} Integer{m}%d ms{e}", t_int);
    webSend(buf);
    sprintf(buf, "{s} Float{m}%d ms{e}", t_float);
    webSend(buf);
    sprintf(buf, "{s} Array{m}%d ms{e}", t_array);
    webSend(buf);
    sprintf(buf, "{s} Calls{m}%d ms{e}", t_call);
    webSend(buf);
    sprintf(buf, "{s} Strings{m}%d ms{e}", t_string);
    webSend(buf);
}

void JsonCall() {
    char buf[128];
    sprintf(buf, ",\"Bench\":{\"Total\":%d", t_total);
    responseAppend(buf);
    sprintf(buf, ",\"Int\":%d", t_int);
    responseAppend(buf);
    sprintf(buf, ",\"Float\":%d", t_float);
    responseAppend(buf);
    sprintf(buf, ",\"Array\":%d", t_array);
    responseAppend(buf);
    sprintf(buf, ",\"Call\":%d", t_call);
    responseAppend(buf);
    sprintf(buf, ",\"Str\":%d}", t_string);
    responseAppend(buf);
}

int main() {
    char buf[64];
    int t0 = 0;
    int t1 = 0;

    printStr("=== TinyC Benchmark ===\n");

    t_start = millis();

    // 1. Integer arithmetic: 100k iterations, 5 ops each = 500k ops
    t0 = millis();
    bench_int();
    t1 = millis();
    t_int = t1 - t0;
    sprintf(buf, "Integer:  %d ms  (500k ops)\n", t_int);
    printString(buf);

    // 2. Float arithmetic: 50k iterations, 5 ops each = 250k ops
    t0 = millis();
    bench_float();
    t1 = millis();
    t_float = t1 - t0;
    sprintf(buf, "Float:    %d ms  (250k ops)\n", t_float);
    printString(buf);

    // 3. Array access: 200 fill + 100k random access
    t0 = millis();
    bench_array();
    t1 = millis();
    t_array = t1 - t0;
    sprintf(buf, "Array:    %d ms  (100k access)\n", t_array);
    printString(buf);

    // 4. Function calls: 100k calls with 3 args
    t0 = millis();
    bench_call();
    t1 = millis();
    t_call = t1 - t0;
    sprintf(buf, "Calls:    %d ms  (100k calls)\n", t_call);
    printString(buf);

    // 5. String operations: 10k iterations
    t0 = millis();
    bench_string();
    t1 = millis();
    t_string = t1 - t0;
    sprintf(buf, "Strings:  %d ms  (10k iters)\n", t_string);
    printString(buf);

    t_total = millis() - t_start;
    sprintf(buf, "── Total: %d ms ──\n", t_total);
    printString(buf);

    return 0;
}

bresser:
// Bresser Weather Station Receiver (CC1101 868 MHz)
// Receives data from Bresser 5-in-1/6-in-1/7-in-1 weather sensors
// Supports weather station + soil moisture sensor (s_type 4)
// Demonstrates: SPI, CC1101 radio config, multi-protocol data decoding
// Hardware: CC1101 module on SPI bus, GDO0 on GPIO for packet detect

#define CS_PIN     8
#define GDO0_PIN   7
#define SPI_MHZ    4

// CC1101 Register addresses
#define REG_IOCFG2   0x00
#define REG_IOCFG0   0x02
#define REG_FIFOTHR  0x03
#define REG_SYNC1    0x04
#define REG_SYNC0    0x05
#define REG_PKTLEN   0x06
#define REG_PKTCTRL0 0x07
#define REG_PKTCTRL1 0x08
#define REG_ADDR     0x09
#define REG_CHANNR   0x0A
#define REG_FSCTRL1  0x0B
#define REG_FSCTRL0  0x0C
#define REG_FREQ2    0x0D
#define REG_FREQ1    0x0E
#define REG_FREQ0    0x0F
#define REG_MDMCFG4  0x10
#define REG_MDMCFG3  0x11
#define REG_MDMCFG2  0x12
#define REG_MDMCFG1  0x13
#define REG_MDMCFG0  0x14
#define REG_DEVIATN  0x15
#define REG_MCSM2    0x16
#define REG_MCSM1    0x17
#define REG_MCSM0    0x18
#define REG_FOCCFG   0x19
#define REG_BSCFG    0x1A
#define REG_AGCCTRL2 0x1B
#define REG_AGCCTRL1 0x1C
#define REG_AGCCTRL0 0x1D
#define REG_FREND1   0x21
#define REG_FREND0   0x22
#define REG_FSCAL3   0x23
#define REG_FSCAL2   0x24
#define REG_FSCAL1   0x25
#define REG_FSCAL0   0x26
#define REG_TEST2    0x2C
#define REG_TEST1    0x2D
#define REG_TEST0    0x2E
#define REG_PATABLE  0x3E
#define REG_FIFO     0x3F

// CC1101 status registers (read with burst bit 0xC0)
#define REG_RSSI     0x34
#define REG_LQI      0x33
#define REG_RXBYTES  0x3B

// CC1101 command strobes
#define CMD_SRES  0x30
#define CMD_SCAL  0x33
#define CMD_SRX   0x34
#define CMD_SIDLE 0x36
#define CMD_SPWD  0x39
#define CMD_SFRX  0x3A

// SPI access modes
#define WRITE_SINGLE 0x00
#define READ_SINGLE  0x80
#define READ_BURST   0xC0
#define WRITE_BURST  0x40

// Bresser protocol
#define MSG_BUF_SIZE 27  // FIFO read size: D4 prefix + 26 data bytes
#define DATA_SIZE    26  // decoded data size (after stripping D4)

// Sensor data - weather station
float br_temp = 0.0;
int   br_hum = 0;
float br_wind_gust = 0.0;
float br_wind_avg = 0.0;
float br_wind_dir = 0.0;
float br_rain = 0.0;
float br_lux = 0.0;
float br_uvi = 0.0;
float br_rssi = 0.0;
int   br_ok = 0;
int   br_id = 0;
int   br_batt = 0;
int   br_cnt = 0;

// Sensor data - soil moisture
float soil_temp = 0.0;
int   soil_moisture = 0;
float soil_rssi = 0.0;
int   soil_ok = 0;
int   soil_id = 0;
int   soil_batt = 0;
int   soil_cnt = 0;

// Raw packet buffer (global for decoder access, 26 bytes after D4)
char msg[DATA_SIZE];

// SPI transfer buffer (reused for all SPI ops)
char spi[28];

// --- CC1101 Low-Level SPI ---

void cc_write_reg(int addr, int val) {
    spi[0] = addr;
    spi[1] = val;
    spiTransfer(1, spi, 2, 1);
}

int cc_read_reg(int addr) {
    spi[0] = addr | 0x80;
    spi[1] = 0;
    spiTransfer(1, spi, 2, 1);
    return spi[1];
}

int cc_read_status(int addr) {
    spi[0] = addr | 0xC0;
    spi[1] = 0;
    spiTransfer(1, spi, 2, 1);
    return spi[1];
}

void cc_strobe(int cmd) {
    spi[0] = cmd;
    spiTransfer(1, spi, 1, 1);
}

void cc_read_burst(int addr, int len) {
    int i;
    spi[0] = addr | 0xC0;
    for (i = 1; i <= len; i++) {
        spi[i] = 0;
    }
    spiTransfer(1, spi, len + 1, 1);
    // results in spi[1..len]
}

void cc_reset() {
    // manual CS toggle for reset sequence
    digitalWrite(CS_PIN, 1);
    delayMicroseconds(5);
    digitalWrite(CS_PIN, 0);
    delayMicroseconds(10);
    digitalWrite(CS_PIN, 1);
    delayMicroseconds(41);
    cc_strobe(CMD_SRES);
    delay(2);
}

// --- CC1101 Init for Bresser 868.3 MHz ---

int cc_init_bresser() {
    // Frequency: 868.3 MHz (26 MHz crystal)
    cc_write_reg(REG_FREQ2, 0x21);
    cc_write_reg(REG_FREQ1, 0x65);
    cc_write_reg(REG_FREQ0, 0x6A);

    // Data rate: 8.21 kbps, BW=270 kHz
    cc_write_reg(REG_MDMCFG4, 0x68);
    cc_write_reg(REG_MDMCFG3, 0x4B);

    // 2-FSK, 16/16 sync word match
    cc_write_reg(REG_MDMCFG2, 0x02);

    // 4 preamble bytes
    cc_write_reg(REG_MDMCFG1, 0x22);
    cc_write_reg(REG_MDMCFG0, 0xF8);

    // Freq deviation 57.129 kHz
    cc_write_reg(REG_DEVIATN, 0x51);

    // IF frequency
    cc_write_reg(REG_FSCTRL1, 0x06);
    cc_write_reg(REG_FSCTRL0, 0x00);

    // Sync word: 0xAA 0x2D (preamble end + first sync byte)
    // First FIFO byte will be 0xD4 (sacrificial, avoids first-byte corruption)
    cc_write_reg(REG_SYNC1, 0xAA);
    cc_write_reg(REG_SYNC0, 0x2D);

    // Fixed packet length = 27 bytes (D4 + 26 data), no CRC
    cc_write_reg(REG_PKTLEN, MSG_BUF_SIZE);
    cc_write_reg(REG_PKTCTRL0, 0x00);
    cc_write_reg(REG_PKTCTRL1, 0x00);

    // GDO0: assert on sync, deassert at end of packet
    cc_write_reg(REG_IOCFG0, 0x06);
    cc_write_reg(REG_IOCFG2, 0x2E);

    // AGC - maximum sensitivity
    cc_write_reg(REG_AGCCTRL2, 0x03);
    cc_write_reg(REG_AGCCTRL1, 0x40);
    cc_write_reg(REG_AGCCTRL0, 0x91);

    // Freq offset compensation
    cc_write_reg(REG_FOCCFG, 0x16);
    cc_write_reg(REG_BSCFG, 0x6C);

    // Front end
    cc_write_reg(REG_FREND1, 0x56);
    cc_write_reg(REG_FREND0, 0x10);

    // Freq synth calibration
    cc_write_reg(REG_FSCAL3, 0xE9);
    cc_write_reg(REG_FSCAL2, 0x2A);
    cc_write_reg(REG_FSCAL1, 0x00);
    cc_write_reg(REG_FSCAL0, 0x1F);

    // Test registers
    cc_write_reg(REG_TEST2, 0x81);
    cc_write_reg(REG_TEST1, 0x35);
    cc_write_reg(REG_TEST0, 0x09);

    // Main Radio State Machine
    cc_write_reg(REG_MCSM2, 0x07);
    // MCSM1: RXOFF_MODE=11 (stay in RX), CCA_MODE=11
    cc_write_reg(REG_MCSM1, 0x3C);
    // MCSM0: FS_AUTOCAL=01 (cal when IDLE->RX/TX)
    cc_write_reg(REG_MCSM0, 0x18);

    // PA Table
    cc_write_reg(REG_PATABLE, 0xC0);

    // Enter IDLE, calibrate, flush RX FIFO, then enter RX
    cc_strobe(CMD_SIDLE);
    delay(1);
    cc_strobe(CMD_SCAL);
    delay(2);
    cc_strobe(CMD_SIDLE);
    delay(1);
    cc_strobe(CMD_SFRX);
    cc_strobe(CMD_SRX);
    delay(2);

    // Retry SRX to ensure we settle into RX mode
    cc_strobe(CMD_SRX);
    delay(2);

    return 1;
}

// --- RSSI Calculation ---

float cc_get_rssi() {
    int raw = cc_read_status(REG_RSSI);
    int rssi;
    if (raw >= 128) {
        rssi = (raw - 256) / 2 - 74;
    } else {
        rssi = raw / 2 - 74;
    }
    return (float)rssi;
}

// --- Bresser 5-in-1 Decoder ---

int decode_5in1() {
    int i;

    // first 13 bytes XOR with next 13 must be 0xFF
    for (i = 0; i < 13; i++) {
        if (((msg[i] ^ msg[i + 13]) & 0xFF) != 0xFF) {
            return 0;
        }
    }

    // checksum: count bits set in bytes 14-25
    int bits_set = 0;
    int expected = msg[13] & 0xFF;
    for (i = 14; i < DATA_SIZE; i++) {
        int b = msg[i] & 0xFF;
        while (b) {
            bits_set = bits_set + (b & 1);
            b = b >> 1;
        }
    }
    if (bits_set != expected) {
        return 0;
    }

    br_id = msg[14] & 0xFF;
    if (msg[25] & 0x80) {
        br_batt = 0;
    } else {
        br_batt = 1;
    }

    // temperature: BCD digits
    int temp_raw = (msg[20] & 0x0F) + ((msg[20] >> 4) & 0x0F) * 10 + (msg[21] & 0x0F) * 100;
    if (msg[25] & 0x0F) {
        temp_raw = 0 - temp_raw;
    }
    br_temp = (float)temp_raw * 0.1;

    // humidity
    br_hum = (msg[22] & 0x0F) + ((msg[22] >> 4) & 0x0F) * 10;

    // wind
    int wdir_raw = ((msg[17] >> 4) & 0x0F) * 225;
    int gust_raw = ((msg[17] & 0x0F) << 8) + (msg[16] & 0xFF);
    int wind_raw = (msg[18] & 0x0F) + ((msg[18] >> 4) & 0x0F) * 10 + (msg[19] & 0x0F) * 100;

    br_wind_dir = (float)wdir_raw * 0.1;
    br_wind_gust = (float)gust_raw * 0.1;
    br_wind_avg = (float)wind_raw * 0.1;

    // rain
    int rain_raw = (msg[23] & 0x0F) + ((msg[23] >> 4) & 0x0F) * 10 + (msg[24] & 0x0F) * 100 + ((msg[24] >> 4) & 0x0F) * 1000;
    br_rain = (float)rain_raw * 0.1;

    return 1;
}

// --- Bresser 6-in-1 Decoder ---

int lfsr_digest16(int start, int bytes, int gen, int key) {
    int sum = 0;
    int k;
    int i;
    for (k = 0; k < bytes; k++) {
        int data = msg[start + k] & 0xFF;
        for (i = 7; i >= 0; i--) {
            if ((data >> i) & 1) {
                sum = sum ^ key;
            }
            if (key & 1) {
                key = (key >> 1) ^ gen;
            } else {
                key = key >> 1;
            }
        }
    }
    return sum;
}

int add_bytes(int start, int num) {
    int result = 0;
    int i;
    for (i = 0; i < num; i++) {
        result = result + (msg[start + i] & 0xFF);
    }
    return result;
}

int decode_6in1() {
    int chkdgst = ((msg[0] & 0xFF) << 8) | (msg[1] & 0xFF);
    int digest = lfsr_digest16(2, 15, 0x8810, 0x5412);
    if (chkdgst != digest) {
        return 0;
    }

    int sum = add_bytes(2, 16);
    if ((sum & 0xFF) != 0xFF) {
        return 0;
    }

    int s_type = (msg[6] >> 4) & 0x0F;
    int id_tmp = ((msg[2] & 0xFF) << 8) | (msg[3] & 0xFF);
    int batt_tmp = (msg[13] >> 1) & 1;
    int flags = msg[16] & 0x0F;

    // Soil moisture sensor (type 4)
    if (s_type == 4) {
        soil_id = id_tmp;
        soil_batt = batt_tmp;
        soil_rssi = br_rssi;

        // temperature (same BCD format as weather)
        int sign = (msg[13] >> 3) & 1;
        int temp_raw = ((msg[12] >> 4) & 0x0F) * 100 + (msg[12] & 0x0F) * 10 + ((msg[13] >> 4) & 0x0F);
        if (sign) {
            temp_raw = temp_raw - 1000;
        }
        soil_temp = (float)temp_raw * 0.1;

        // humidity field (1-16) -> moisture percentage
        // Maps to: 0,7,13,20,27,33,40,47,53,60,67,73,80,87,93,99
        int hum_idx = ((msg[14] >> 4) & 0x0F) * 10 + (msg[14] & 0x0F);
        if (hum_idx >= 1 && hum_idx <= 16) {
            if (hum_idx <= 1) {
                soil_moisture = 0;
            } else if (hum_idx >= 16) {
                soil_moisture = 99;
            } else {
                soil_moisture = ((hum_idx - 1) * 100 + 8) / 15;
            }
        } else {
            soil_moisture = 0;
        }
        return 2;  // soil sensor
    }

    // Weather station (type 1) or other types
    br_id = id_tmp;
    br_batt = batt_tmp;

    // temperature + humidity (flags == 0)
    if (flags == 0) {
        int sign = (msg[13] >> 3) & 1;
        int temp_raw = ((msg[12] >> 4) & 0x0F) * 100 + (msg[12] & 0x0F) * 10 + ((msg[13] >> 4) & 0x0F);
        if (sign) {
            temp_raw = temp_raw - 1000;
        }
        br_temp = (float)temp_raw * 0.1;
        br_hum = ((msg[14] >> 4) & 0x0F) * 10 + (msg[14] & 0x0F);
    }

    // wind (inverted bytes, mask with 0xFF to avoid sign extension)
    int im7 = (msg[7] ^ 0xFF) & 0xFF;
    int im8 = (msg[8] ^ 0xFF) & 0xFF;
    int im9 = (msg[9] ^ 0xFF) & 0xFF;
    if (im7 <= 0x99 && im8 <= 0x99 && im9 <= 0x99) {
        int gust_raw = ((im7 >> 4) & 0x0F) * 100 + (im7 & 0x0F) * 10 + ((im8 >> 4) & 0x0F);
        int wavg_raw = ((im9 >> 4) & 0x0F) * 100 + (im9 & 0x0F) * 10 + (im8 & 0x0F);
        int wdir_raw = ((msg[10] >> 4) & 0x0F) * 100 + (msg[10] & 0x0F) * 10 + ((msg[11] >> 4) & 0x0F);
        br_wind_gust = (float)gust_raw * 0.1;
        br_wind_avg = (float)wavg_raw * 0.1;
        br_wind_dir = (float)wdir_raw;
    }

    // rain (inverted, flags == 1)
    if (flags == 1) {
        int im12 = (msg[12] ^ 0xFF) & 0xFF;
        int im13 = (msg[13] ^ 0xFF) & 0xFF;
        int im14 = (msg[14] ^ 0xFF) & 0xFF;
        int rain_raw = ((im12 >> 4) & 0x0F) * 100000 + (im12 & 0x0F) * 10000 + ((im13 >> 4) & 0x0F) * 1000 + (im13 & 0x0F) * 100 + ((im14 >> 4) & 0x0F) * 10 + (im14 & 0x0F);
        br_rain = (float)rain_raw * 0.1;
    }

    // UV Index (6-in-1): inverted bytes 15-16, BCD, ×0.1
    int im15 = (msg[15] ^ 0xFF) & 0xFF;
    int im16 = (msg[16] ^ 0xFF) & 0xFF;
    if ((msg[16] & 0x0F) == 0 && im15 <= 0x99 && (im16 & 0xF0) <= 0x90) {
        int uv_raw = ((im15 >> 4) & 0x0F) * 100 + (im15 & 0x0F) * 10 + ((im16 >> 4) & 0x0F);
        br_uvi = (float)uv_raw * 0.1;
    }

    return 1;
}

// --- Bresser 7-in-1 Decoder ---

// de-whitened message buffer
char msgw[DATA_SIZE];

int decode_7in1() {
    int i;

    // data de-whitening (26 bytes)
    for (i = 0; i < DATA_SIZE; i++) {
        msgw[i] = msg[i] ^ 0xAA;
    }

    // LFSR-16 digest check (mask with 0xFF to avoid sign extension)
    int chkdgst = ((msgw[0] & 0xFF) << 8) | (msgw[1] & 0xFF);
    int digest = 0;
    int key = 0xBA95;
    int gen = 0x8810;
    int k;
    for (k = 0; k < 23; k++) {
        int data = msgw[k + 2] & 0xFF;
        for (i = 7; i >= 0; i--) {
            if ((data >> i) & 1) {
                digest = digest ^ key;
            }
            if (key & 1) {
                key = (key >> 1) ^ gen;
            } else {
                key = key >> 1;
            }
        }
    }
    if ((chkdgst ^ digest) != 0x6DF1) {
        return 0;
    }

    br_id = ((msgw[2] & 0xFF) << 8) | (msgw[3] & 0xFF);
    int s_type = (msg[6] >> 4) & 0x0F;
    int flags = msgw[15] & 0x0F;
    if ((flags & 0x06) == 0x06) {
        br_batt = 0;
    } else {
        br_batt = 1;
    }

    // Weather station (type 1)
    if (s_type == 1) {
        int wdir = ((msgw[4] >> 4) & 0x0F) * 100 + (msgw[4] & 0x0F) * 10 + ((msgw[5] >> 4) & 0x0F);
        int wgst = ((msgw[7] >> 4) & 0x0F) * 100 + (msgw[7] & 0x0F) * 10 + ((msgw[8] >> 4) & 0x0F);
        int wavg = (msgw[8] & 0x0F) * 100 + ((msgw[9] >> 4) & 0x0F) * 10 + (msgw[9] & 0x0F);
        int rain_raw = ((msgw[10] >> 4) & 0x0F) * 100000 + (msgw[10] & 0x0F) * 10000 + ((msgw[11] >> 4) & 0x0F) * 1000 + (msgw[11] & 0x0F) * 100 + ((msgw[12] >> 4) & 0x0F) * 10 + (msgw[12] & 0x0F);
        int temp_raw = ((msgw[14] >> 4) & 0x0F) * 100 + (msgw[14] & 0x0F) * 10 + ((msgw[15] >> 4) & 0x0F);
        int humidity = ((msgw[16] >> 4) & 0x0F) * 10 + (msgw[16] & 0x0F);

        float temp_c = (float)temp_raw * 0.1;
        if (temp_raw > 600) {
            temp_c = (float)(temp_raw - 1000) * 0.1;
        }

        br_temp = temp_c;
        br_hum = humidity;
        br_wind_dir = (float)wdir;
        br_wind_gust = (float)wgst * 0.1;
        br_wind_avg = (float)wavg * 0.1;
        br_rain = (float)rain_raw * 0.1;

        // Light (lux) — 6 BCD digits in de-whitened bytes 17-19
        int lght_raw = ((msgw[17] >> 4) & 0x0F) * 100000 + (msgw[17] & 0x0F) * 10000 + ((msgw[18] >> 4) & 0x0F) * 1000 + (msgw[18] & 0x0F) * 100 + ((msgw[19] >> 4) & 0x0F) * 10 + (msgw[19] & 0x0F);
        br_lux = (float)lght_raw;

        // UV Index — 3 BCD digits in de-whitened bytes 20-21, ×0.1
        int uv_raw = ((msgw[20] >> 4) & 0x0F) * 100 + (msgw[20] & 0x0F) * 10 + ((msgw[21] >> 4) & 0x0F);
        br_uvi = (float)uv_raw * 0.1;

        return 1;
    }

    // Soil moisture sensor (type 4) - uses raw msg[], NOT de-whitened
    if (s_type == 4) {
        int temp_raw = (msg[20] & 0x0F) + ((msg[20] >> 4) & 0x0F) * 10 + (msg[21] & 0x0F) * 100;
        if (msg[25] & 0x0F) {
            temp_raw = 0 - temp_raw;
        }
        soil_temp = (float)temp_raw * 0.1;

        // humidity field (1-16) -> moisture percentage
        int hum_idx = (msg[22] & 0x0F) + ((msg[22] >> 4) & 0x0F) * 10;
        if (hum_idx >= 1 && hum_idx <= 16) {
            if (hum_idx <= 1) {
                soil_moisture = 0;
            } else if (hum_idx >= 16) {
                soil_moisture = 99;
            } else {
                soil_moisture = ((hum_idx - 1) * 100 + 8) / 15;
            }
        } else {
            soil_moisture = 0;
        }

        soil_id = br_id;
        soil_batt = br_batt;
        soil_rssi = br_rssi;
        return 2;  // soil sensor
    }

    // Unknown sensor type - valid LFSR but we don't decode it
    return 0;
}

// --- Message Dispatcher ---

int decode_message() {
    int res;
    res = decode_7in1();
    if (res) return res;  // 1=weather, 2=soil
    res = decode_6in1();
    if (res) return res;
    res = decode_5in1();
    if (res) return 1;
    return 0;
}

// --- Receive Message ---

int receive_message() {
    int rxBytes = cc_read_status(REG_RXBYTES);

    if (rxBytes >= MSG_BUF_SIZE) {
        // burst read FIFO (27 bytes: D4 + 26 data bytes)
        cc_read_burst(REG_FIFO, MSG_BUF_SIZE);

        // get RSSI before flushing
        br_rssi = cc_get_rssi();

        // flush and restart RX
        cc_strobe(CMD_SIDLE);
        cc_strobe(CMD_SFRX);
        cc_strobe(CMD_SRX);
        delay(1);

        // With sync AA 2D, spi[1]=D4 (sacrificial), spi[2..27]=data
        // Copy data bytes: spi[2..27] -> msg[0..25]
        int i;
        for (i = 0; i < DATA_SIZE; i++) {
            msg[i] = spi[i + 2];
        }

        return decode_message();
    }
    return 0;
}

// --- Callbacks ---

void Every50ms() {
    // Called 20x/sec - non-blocking check for CC1101 packet
    int res = receive_message();
    if (res == 1) {
        br_ok = 1;
        br_cnt = br_cnt + 1;
    }
    if (res == 2) {
        soil_ok = 1;
        soil_cnt = soil_cnt + 1;
    }
}

void WebCall() {
    char out[80];
    if (br_ok) {
        sprintf(out, "{s}Bresser ID{m}0x%04X{e}", br_id);
        webSend(out);
        sprintf(out, "{s}Temperature{m}%.1f C{e}", br_temp);
        webSend(out);
        sprintf(out, "{s}Humidity{m}%d %%{e}", br_hum);
        webSend(out);
        sprintf(out, "{s}Wind Gust{m}%.1f m/s{e}", br_wind_gust);
        webSend(out);
        sprintf(out, "{s}Wind Avg{m}%.1f m/s{e}", br_wind_avg);
        webSend(out);
        sprintf(out, "{s}Wind Dir{m}%.0f deg{e}", br_wind_dir);
        webSend(out);
        sprintf(out, "{s}Rain{m}%.1f mm{e}", br_rain);
        webSend(out);
        sprintf(out, "{s}Brightness{m}%.0f lux{e}", br_lux);
        webSend(out);
        sprintf(out, "{s}UV Index{m}%.1f{e}", br_uvi);
        webSend(out);
        sprintf(out, "{s}RSSI{m}%.0f dBm{e}", br_rssi);
        webSend(out);
        if (br_batt) {
            webSend("{s}Battery{m}OK{e}");
        } else {
            webSend("{s}Battery{m}Low{e}");
        }
        sprintf(out, "{s}Packets{m}%d{e}", br_cnt);
        webSend(out);
    } else {
        webSend("{s}Bresser{m}waiting for data{e}");
    }
    if (soil_ok) {
        sprintf(out, "{s}Soil ID{m}0x%04X{e}", soil_id);
        webSend(out);
        sprintf(out, "{s}Soil Temp{m}%.1f C{e}", soil_temp);
        webSend(out);
        sprintf(out, "{s}Soil Moisture{m}%d %%{e}", soil_moisture);
        webSend(out);
        sprintf(out, "{s}Soil RSSI{m}%.0f dBm{e}", soil_rssi);
        webSend(out);
        if (soil_batt) {
            webSend("{s}Soil Battery{m}OK{e}");
        } else {
            webSend("{s}Soil Battery{m}Low{e}");
        }
        sprintf(out, "{s}Soil Packets{m}%d{e}", soil_cnt);
        webSend(out);
    }
}

void JsonCall() {
    char out[80];
    if (br_ok) {
        sprintf(out, ",\"Bresser\":{\"ID\":\"%04X\"", br_id);
        responseAppend(out);
        sprintf(out, ",\"Temp\":%.1f", br_temp);
        responseAppend(out);
        sprintf(out, ",\"Hum\":%d", br_hum);
        responseAppend(out);
        sprintf(out, ",\"WindGust\":%.1f", br_wind_gust);
        responseAppend(out);
        sprintf(out, ",\"WindAvg\":%.1f", br_wind_avg);
        responseAppend(out);
        sprintf(out, ",\"WindDir\":%.0f", br_wind_dir);
        responseAppend(out);
        sprintf(out, ",\"Rain\":%.1f", br_rain);
        responseAppend(out);
        sprintf(out, ",\"Lux\":%.0f", br_lux);
        responseAppend(out);
        sprintf(out, ",\"UVI\":%.1f", br_uvi);
        responseAppend(out);
        sprintf(out, ",\"RSSI\":%.0f", br_rssi);
        responseAppend(out);
        sprintf(out, ",\"Batt\":%d", br_batt);
        responseAppend(out);
        sprintf(out, ",\"Cnt\":%d}", br_cnt);
        responseAppend(out);
    }
    if (soil_ok) {
        sprintf(out, ",\"Soil\":{\"ID\":\"%04X\"", soil_id);
        responseAppend(out);
        sprintf(out, ",\"Temp\":%.1f", soil_temp);
        responseAppend(out);
        sprintf(out, ",\"Moisture\":%d", soil_moisture);
        responseAppend(out);
        sprintf(out, ",\"RSSI\":%.0f", soil_rssi);
        responseAppend(out);
        sprintf(out, ",\"Batt\":%d", soil_batt);
        responseAppend(out);
        sprintf(out, ",\"Cnt\":%d}", soil_cnt);
        responseAppend(out);
    }
}

int main() {
    // init SPI (CS managed manually during reset, then by driver)
    spiInit(-1, -1, -1, SPI_MHZ);

    // init GDO0 as input
    gpioInit(GDO0_PIN, 0);

    // CC1101 reset needs manual CS toggling - do before spiSetCS claims the pin
    gpioInit(CS_PIN, 1);
    cc_reset();

    // now let SPI driver manage CS
    spiSetCS(1, CS_PIN);

    // Check CC1101 version register
    int ver = cc_read_status(0x31);
    char buf[64];
    sprintf(buf, "CC1101 version: 0x%02X\n", ver);
    printString(buf);

    if (ver == 0 || ver == 0xFF) {
        printStr("ERROR: CC1101 not found\n");
        return 1;
    }

    if (!cc_init_bresser()) {
        printStr("ERROR: CC1101 init failed\n");
        return 1;
    }

    br_ok = 0;
    br_cnt = 0;
    soil_ok = 0;
    soil_cnt = 0;

    printStr("Bresser CC1101 receiver ready\n");
    return 0;
}

bresser_chart:
// Bresser Weather Station + 24h Google Charts (CC1101 868 MHz)
// Full Bresser 5/6/7-in-1 receiver with 6 ring-buffer charts
// 288 points per chart (every 5 min, 24 hours)
// Heap: 6 × 288 = 1728 slots (of 8192 available on ESP32)

#define CS_PIN     8
#define GDO0_PIN   7
#define SPI_MHZ    4

// CC1101 Register addresses
#define REG_IOCFG2   0x00
#define REG_IOCFG0   0x02
#define REG_FIFOTHR  0x03
#define REG_SYNC1    0x04
#define REG_SYNC0    0x05
#define REG_PKTLEN   0x06
#define REG_PKTCTRL0 0x07
#define REG_PKTCTRL1 0x08
#define REG_ADDR     0x09
#define REG_CHANNR   0x0A
#define REG_FSCTRL1  0x0B
#define REG_FSCTRL0  0x0C
#define REG_FREQ2    0x0D
#define REG_FREQ1    0x0E
#define REG_FREQ0    0x0F
#define REG_MDMCFG4  0x10
#define REG_MDMCFG3  0x11
#define REG_MDMCFG2  0x12
#define REG_MDMCFG1  0x13
#define REG_MDMCFG0  0x14
#define REG_DEVIATN  0x15
#define REG_MCSM2    0x16
#define REG_MCSM1    0x17
#define REG_MCSM0    0x18
#define REG_FOCCFG   0x19
#define REG_BSCFG    0x1A
#define REG_AGCCTRL2 0x1B
#define REG_AGCCTRL1 0x1C
#define REG_AGCCTRL0 0x1D
#define REG_FREND1   0x21
#define REG_FREND0   0x22
#define REG_FSCAL3   0x23
#define REG_FSCAL2   0x24
#define REG_FSCAL1   0x25
#define REG_FSCAL0   0x26
#define REG_TEST2    0x2C
#define REG_TEST1    0x2D
#define REG_TEST0    0x2E
#define REG_PATABLE  0x3E
#define REG_FIFO     0x3F

// CC1101 status registers
#define REG_RSSI     0x34
#define REG_LQI      0x33
#define REG_RXBYTES  0x3B

// CC1101 command strobes
#define CMD_SRES  0x30
#define CMD_SCAL  0x33
#define CMD_SRX   0x34
#define CMD_SIDLE 0x36
#define CMD_SPWD  0x39
#define CMD_SFRX  0x3A

// SPI access modes
#define WRITE_SINGLE 0x00
#define READ_SINGLE  0x80
#define READ_BURST   0xC0
#define WRITE_BURST  0x40

// Bresser protocol
#define MSG_BUF_SIZE 27
#define DATA_SIZE    26

// Chart ring buffer: 288 points = 24h at 5-min intervals
#define NPTS 288
#define STORE_INTERVAL 300  // seconds between samples (5 min)

// Sensor data - weather station (live values)
float br_temp = 0.0;
int   br_hum = 0;
float br_wind_gust = 0.0;
float br_wind_avg = 0.0;
float br_wind_dir = 0.0;
float br_rain = 0.0;
float br_rssi = 0.0;
int   br_ok = 0;
int   br_id = 0;
int   br_batt = 0;
int   br_cnt = 0;

// Sensor data - soil moisture
float soil_temp = 0.0;
int   soil_moisture = 0;
float soil_rssi = 0.0;
int   soil_ok = 0;
int   soil_id = 0;
int   soil_batt = 0;
int   soil_cnt = 0;

// Additional sensor data (e.g. from I2C light/UV sensors)
float br_lux = 0.0;     // brightness in lux
float br_uvi = 0.0;     // UV index

// Ring buffers for 24h charts (stored as int × 10 for 1-decimal precision)
// Charted variables: temp, hum, windavg, rain, brightness, uvi
int h_temp[NPTS];
int h_hum[NPTS];
int h_wavg[NPTS];
int h_rain[NPTS];
int h_lux[NPTS];
int h_uvi[NPTS];
int h_pos = 0;       // ring buffer write position
int h_count = 0;     // total samples stored (saturates at NPTS)
int sec_cnt = 0;     // seconds counter for store interval

// Raw packet buffer and SPI buffer
char msg[DATA_SIZE];
char spi[28];

// --- CC1101 Low-Level SPI ---

void cc_write_reg(int addr, int val) {
    spi[0] = addr;
    spi[1] = val;
    spiTransfer(1, spi, 2, 1);
}

int cc_read_reg(int addr) {
    spi[0] = addr | 0x80;
    spi[1] = 0;
    spiTransfer(1, spi, 2, 1);
    return spi[1];
}

int cc_read_status(int addr) {
    spi[0] = addr | 0xC0;
    spi[1] = 0;
    spiTransfer(1, spi, 2, 1);
    return spi[1];
}

void cc_strobe(int cmd) {
    spi[0] = cmd;
    spiTransfer(1, spi, 1, 1);
}

void cc_read_burst(int addr, int len) {
    int i;
    spi[0] = addr | 0xC0;
    for (i = 1; i <= len; i++) {
        spi[i] = 0;
    }
    spiTransfer(1, spi, len + 1, 1);
}

void cc_reset() {
    digitalWrite(CS_PIN, 1);
    delayMicroseconds(5);
    digitalWrite(CS_PIN, 0);
    delayMicroseconds(10);
    digitalWrite(CS_PIN, 1);
    delayMicroseconds(41);
    cc_strobe(CMD_SRES);
    delay(2);
}

// --- CC1101 Init for Bresser 868.3 MHz ---

int cc_init_bresser() {
    cc_write_reg(REG_FREQ2, 0x21);
    cc_write_reg(REG_FREQ1, 0x65);
    cc_write_reg(REG_FREQ0, 0x6A);
    cc_write_reg(REG_MDMCFG4, 0x68);
    cc_write_reg(REG_MDMCFG3, 0x4B);
    cc_write_reg(REG_MDMCFG2, 0x02);
    cc_write_reg(REG_MDMCFG1, 0x22);
    cc_write_reg(REG_MDMCFG0, 0xF8);
    cc_write_reg(REG_DEVIATN, 0x51);
    cc_write_reg(REG_FSCTRL1, 0x06);
    cc_write_reg(REG_FSCTRL0, 0x00);
    cc_write_reg(REG_SYNC1, 0xAA);
    cc_write_reg(REG_SYNC0, 0x2D);
    cc_write_reg(REG_PKTLEN, MSG_BUF_SIZE);
    cc_write_reg(REG_PKTCTRL0, 0x00);
    cc_write_reg(REG_PKTCTRL1, 0x00);
    cc_write_reg(REG_IOCFG0, 0x06);
    cc_write_reg(REG_IOCFG2, 0x2E);
    cc_write_reg(REG_AGCCTRL2, 0x03);
    cc_write_reg(REG_AGCCTRL1, 0x40);
    cc_write_reg(REG_AGCCTRL0, 0x91);
    cc_write_reg(REG_FOCCFG, 0x16);
    cc_write_reg(REG_BSCFG, 0x6C);
    cc_write_reg(REG_FREND1, 0x56);
    cc_write_reg(REG_FREND0, 0x10);
    cc_write_reg(REG_FSCAL3, 0xE9);
    cc_write_reg(REG_FSCAL2, 0x2A);
    cc_write_reg(REG_FSCAL1, 0x00);
    cc_write_reg(REG_FSCAL0, 0x1F);
    cc_write_reg(REG_TEST2, 0x81);
    cc_write_reg(REG_TEST1, 0x35);
    cc_write_reg(REG_TEST0, 0x09);
    cc_write_reg(REG_MCSM2, 0x07);
    cc_write_reg(REG_MCSM1, 0x3C);
    cc_write_reg(REG_MCSM0, 0x18);
    cc_write_reg(REG_PATABLE, 0xC0);

    cc_strobe(CMD_SIDLE);
    delay(1);
    cc_strobe(CMD_SCAL);
    delay(2);
    cc_strobe(CMD_SIDLE);
    delay(1);
    cc_strobe(CMD_SFRX);
    cc_strobe(CMD_SRX);
    delay(2);
    cc_strobe(CMD_SRX);
    delay(2);
    return 1;
}

// --- RSSI Calculation ---

float cc_get_rssi() {
    int raw = cc_read_status(REG_RSSI);
    int rssi;
    if (raw >= 128) {
        rssi = (raw - 256) / 2 - 74;
    } else {
        rssi = raw / 2 - 74;
    }
    return (float)rssi;
}

// --- Bresser 5-in-1 Decoder ---

int decode_5in1() {
    int i;
    for (i = 0; i < 13; i++) {
        if (((msg[i] ^ msg[i + 13]) & 0xFF) != 0xFF) {
            return 0;
        }
    }
    int bits_set = 0;
    int expected = msg[13] & 0xFF;
    for (i = 14; i < DATA_SIZE; i++) {
        int b = msg[i] & 0xFF;
        while (b) {
            bits_set = bits_set + (b & 1);
            b = b >> 1;
        }
    }
    if (bits_set != expected) return 0;

    br_id = msg[14] & 0xFF;
    if (msg[25] & 0x80) { br_batt = 0; } else { br_batt = 1; }

    int temp_raw = (msg[20] & 0x0F) + ((msg[20] >> 4) & 0x0F) * 10 + (msg[21] & 0x0F) * 100;
    if (msg[25] & 0x0F) { temp_raw = 0 - temp_raw; }
    br_temp = (float)temp_raw * 0.1;
    br_hum = (msg[22] & 0x0F) + ((msg[22] >> 4) & 0x0F) * 10;

    int wdir_raw = ((msg[17] >> 4) & 0x0F) * 225;
    int gust_raw = ((msg[17] & 0x0F) << 8) + (msg[16] & 0xFF);
    int wind_raw = (msg[18] & 0x0F) + ((msg[18] >> 4) & 0x0F) * 10 + (msg[19] & 0x0F) * 100;
    br_wind_dir = (float)wdir_raw * 0.1;
    br_wind_gust = (float)gust_raw * 0.1;
    br_wind_avg = (float)wind_raw * 0.1;

    int rain_raw = (msg[23] & 0x0F) + ((msg[23] >> 4) & 0x0F) * 10 + (msg[24] & 0x0F) * 100 + ((msg[24] >> 4) & 0x0F) * 1000;
    br_rain = (float)rain_raw * 0.1;
    return 1;
}

// --- Bresser 6-in-1 Decoder ---

int lfsr_digest16(int start, int bytes, int gen, int key) {
    int sum = 0;
    int k;
    int i;
    for (k = 0; k < bytes; k++) {
        int data = msg[start + k] & 0xFF;
        for (i = 7; i >= 0; i--) {
            if ((data >> i) & 1) { sum = sum ^ key; }
            if (key & 1) { key = (key >> 1) ^ gen; } else { key = key >> 1; }
        }
    }
    return sum;
}

int add_bytes(int start, int num) {
    int result = 0;
    int i;
    for (i = 0; i < num; i++) {
        result = result + (msg[start + i] & 0xFF);
    }
    return result;
}

int decode_6in1() {
    int chkdgst = ((msg[0] & 0xFF) << 8) | (msg[1] & 0xFF);
    int digest = lfsr_digest16(2, 15, 0x8810, 0x5412);
    if (chkdgst != digest) return 0;

    int sum = add_bytes(2, 16);
    if ((sum & 0xFF) != 0xFF) return 0;

    int s_type = (msg[6] >> 4) & 0x0F;
    int id_tmp = ((msg[2] & 0xFF) << 8) | (msg[3] & 0xFF);
    int batt_tmp = (msg[13] >> 1) & 1;
    int flags = msg[16] & 0x0F;

    if (s_type == 4) {
        soil_id = id_tmp;
        soil_batt = batt_tmp;
        soil_rssi = br_rssi;
        int sign = (msg[13] >> 3) & 1;
        int temp_raw = ((msg[12] >> 4) & 0x0F) * 100 + (msg[12] & 0x0F) * 10 + ((msg[13] >> 4) & 0x0F);
        if (sign) { temp_raw = temp_raw - 1000; }
        soil_temp = (float)temp_raw * 0.1;
        int hum_idx = ((msg[14] >> 4) & 0x0F) * 10 + (msg[14] & 0x0F);
        if (hum_idx >= 1 && hum_idx <= 16) {
            if (hum_idx <= 1) { soil_moisture = 0; }
            else if (hum_idx >= 16) { soil_moisture = 99; }
            else { soil_moisture = ((hum_idx - 1) * 100 + 8) / 15; }
        } else { soil_moisture = 0; }
        return 2;
    }

    br_id = id_tmp;
    br_batt = batt_tmp;
    if (flags == 0) {
        int sign = (msg[13] >> 3) & 1;
        int temp_raw = ((msg[12] >> 4) & 0x0F) * 100 + (msg[12] & 0x0F) * 10 + ((msg[13] >> 4) & 0x0F);
        if (sign) { temp_raw = temp_raw - 1000; }
        br_temp = (float)temp_raw * 0.1;
        br_hum = ((msg[14] >> 4) & 0x0F) * 10 + (msg[14] & 0x0F);
    }

    int im7 = (msg[7] ^ 0xFF) & 0xFF;
    int im8 = (msg[8] ^ 0xFF) & 0xFF;
    int im9 = (msg[9] ^ 0xFF) & 0xFF;
    if (im7 <= 0x99 && im8 <= 0x99 && im9 <= 0x99) {
        int gust_raw = ((im7 >> 4) & 0x0F) * 100 + (im7 & 0x0F) * 10 + ((im8 >> 4) & 0x0F);
        int wavg_raw = ((im9 >> 4) & 0x0F) * 100 + (im9 & 0x0F) * 10 + (im8 & 0x0F);
        int wdir_raw = ((msg[10] >> 4) & 0x0F) * 100 + (msg[10] & 0x0F) * 10 + ((msg[11] >> 4) & 0x0F);
        br_wind_gust = (float)gust_raw * 0.1;
        br_wind_avg = (float)wavg_raw * 0.1;
        br_wind_dir = (float)wdir_raw;
    }

    if (flags == 1) {
        int im12 = (msg[12] ^ 0xFF) & 0xFF;
        int im13 = (msg[13] ^ 0xFF) & 0xFF;
        int im14 = (msg[14] ^ 0xFF) & 0xFF;
        int rain_raw = ((im12 >> 4) & 0x0F) * 100000 + (im12 & 0x0F) * 10000 + ((im13 >> 4) & 0x0F) * 1000 + (im13 & 0x0F) * 100 + ((im14 >> 4) & 0x0F) * 10 + (im14 & 0x0F);
        br_rain = (float)rain_raw * 0.1;
    }

    // UV Index (6-in-1): inverted bytes 15-16, BCD, ×0.1
    int im15 = (msg[15] ^ 0xFF) & 0xFF;
    int im16 = (msg[16] ^ 0xFF) & 0xFF;
    if ((msg[16] & 0x0F) == 0 && im15 <= 0x99 && (im16 & 0xF0) <= 0x90) {
        int uv_raw = ((im15 >> 4) & 0x0F) * 100 + (im15 & 0x0F) * 10 + ((im16 >> 4) & 0x0F);
        br_uvi = (float)uv_raw * 0.1;
    }

    return 1;
}

// --- Bresser 7-in-1 Decoder ---

char msgw[DATA_SIZE];

int decode_7in1() {
    int i;
    for (i = 0; i < DATA_SIZE; i++) {
        msgw[i] = msg[i] ^ 0xAA;
    }

    int chkdgst = ((msgw[0] & 0xFF) << 8) | (msgw[1] & 0xFF);
    int digest = 0;
    int key = 0xBA95;
    int gen = 0x8810;
    int k;
    for (k = 0; k < 23; k++) {
        int data = msgw[k + 2] & 0xFF;
        for (i = 7; i >= 0; i--) {
            if ((data >> i) & 1) { digest = digest ^ key; }
            if (key & 1) { key = (key >> 1) ^ gen; } else { key = key >> 1; }
        }
    }
    if ((chkdgst ^ digest) != 0x6DF1) return 0;

    br_id = ((msgw[2] & 0xFF) << 8) | (msgw[3] & 0xFF);
    int s_type = (msg[6] >> 4) & 0x0F;
    int flags = msgw[15] & 0x0F;
    if ((flags & 0x06) == 0x06) { br_batt = 0; } else { br_batt = 1; }

    if (s_type == 1) {
        int wdir = ((msgw[4] >> 4) & 0x0F) * 100 + (msgw[4] & 0x0F) * 10 + ((msgw[5] >> 4) & 0x0F);
        int wgst = ((msgw[7] >> 4) & 0x0F) * 100 + (msgw[7] & 0x0F) * 10 + ((msgw[8] >> 4) & 0x0F);
        int wavg = (msgw[8] & 0x0F) * 100 + ((msgw[9] >> 4) & 0x0F) * 10 + (msgw[9] & 0x0F);
        int rain_raw = ((msgw[10] >> 4) & 0x0F) * 100000 + (msgw[10] & 0x0F) * 10000 + ((msgw[11] >> 4) & 0x0F) * 1000 + (msgw[11] & 0x0F) * 100 + ((msgw[12] >> 4) & 0x0F) * 10 + (msgw[12] & 0x0F);
        int temp_raw = ((msgw[14] >> 4) & 0x0F) * 100 + (msgw[14] & 0x0F) * 10 + ((msgw[15] >> 4) & 0x0F);
        int humidity = ((msgw[16] >> 4) & 0x0F) * 10 + (msgw[16] & 0x0F);
        float temp_c = (float)temp_raw * 0.1;
        if (temp_raw > 600) { temp_c = (float)(temp_raw - 1000) * 0.1; }
        br_temp = temp_c;
        br_hum = humidity;
        br_wind_dir = (float)wdir;
        br_wind_gust = (float)wgst * 0.1;
        br_wind_avg = (float)wavg * 0.1;
        br_rain = (float)rain_raw * 0.1;

        // Light (lux) — 6 BCD digits in de-whitened bytes 17-19
        int lght_raw = ((msgw[17] >> 4) & 0x0F) * 100000 + (msgw[17] & 0x0F) * 10000 + ((msgw[18] >> 4) & 0x0F) * 1000 + (msgw[18] & 0x0F) * 100 + ((msgw[19] >> 4) & 0x0F) * 10 + (msgw[19] & 0x0F);
        br_lux = (float)lght_raw;

        // UV Index — 3 BCD digits in de-whitened bytes 20-21, ×0.1
        int uv_raw = ((msgw[20] >> 4) & 0x0F) * 100 + (msgw[20] & 0x0F) * 10 + ((msgw[21] >> 4) & 0x0F);
        br_uvi = (float)uv_raw * 0.1;

        return 1;
    }

    if (s_type == 4) {
        int temp_raw = (msg[20] & 0x0F) + ((msg[20] >> 4) & 0x0F) * 10 + (msg[21] & 0x0F) * 100;
        if (msg[25] & 0x0F) { temp_raw = 0 - temp_raw; }
        soil_temp = (float)temp_raw * 0.1;
        int hum_idx = (msg[22] & 0x0F) + ((msg[22] >> 4) & 0x0F) * 10;
        if (hum_idx >= 1 && hum_idx <= 16) {
            if (hum_idx <= 1) { soil_moisture = 0; }
            else if (hum_idx >= 16) { soil_moisture = 99; }
            else { soil_moisture = ((hum_idx - 1) * 100 + 8) / 15; }
        } else { soil_moisture = 0; }
        soil_id = br_id;
        soil_batt = br_batt;
        soil_rssi = br_rssi;
        return 2;
    }
    return 0;
}

// --- Message Dispatcher ---

int decode_message() {
    int res;
    res = decode_7in1();
    if (res) return res;
    res = decode_6in1();
    if (res) return res;
    res = decode_5in1();
    if (res) return 1;
    return 0;
}

// --- Receive Message ---

int receive_message() {
    int rxBytes = cc_read_status(REG_RXBYTES);
    if (rxBytes >= MSG_BUF_SIZE) {
        cc_read_burst(REG_FIFO, MSG_BUF_SIZE);
        br_rssi = cc_get_rssi();
        cc_strobe(CMD_SIDLE);
        cc_strobe(CMD_SFRX);
        cc_strobe(CMD_SRX);
        delay(1);
        int i;
        for (i = 0; i < DATA_SIZE; i++) {
            msg[i] = spi[i + 2];
        }
        return decode_message();
    }
    return 0;
}

// --- Callbacks ---

void Every50ms() {
    int res = receive_message();
    if (res == 1) {
        br_ok = 1;
        br_cnt = br_cnt + 1;
    }
    if (res == 2) {
        soil_ok = 1;
        soil_cnt = soil_cnt + 1;
    }
}

void EverySecond() {
    sec_cnt++;
    if (sec_cnt >= STORE_INTERVAL && br_ok) {
        sec_cnt = 0;
        // Store current values as int (×10 for decimal values)
        h_temp[h_pos] = (int)(br_temp * 10.0);
        h_hum[h_pos] = br_hum;
        h_wavg[h_pos] = (int)(br_wind_avg * 10.0);
        h_rain[h_pos] = (int)(br_rain * 10.0);
        h_lux[h_pos] = (int)(br_lux * 10.0);
        h_uvi[h_pos] = (int)(br_uvi * 10.0);
        h_pos++;
        if (h_pos >= NPTS) h_pos = 0;
        if (h_count < NPTS) h_count++;
    }
}

// --- Chart Helper: get value from ring buffer by chart_id ---
// chart_id: 0=temp, 1=hum, 2=windavg, 3=rain, 4=lux, 5=uvi

int get_hist(int chart_id, int idx) {
    if (chart_id == 0) return h_temp[idx];
    if (chart_id == 1) return h_hum[idx];
    if (chart_id == 2) return h_wavg[idx];
    if (chart_id == 3) return h_rain[idx];
    if (chart_id == 4) return h_lux[idx];
    if (chart_id == 5) return h_uvi[idx];
    return 0;
}

// Emit chart data rows for one variable
// chart_id selects the array, scale10: 1=values are ×10, 0=raw int
void emit_chart(int chart_id, int scale10) {
    char buf[80];
    int i;
    int n = h_count;

    i = 0;
    while (i < n) {
        int idx = h_pos - n + i;
        if (idx < 0) idx = idx + NPTS;
        int val = get_hist(chart_id, idx);

        // Time axis: hours×10 (negative = past, 0 = now)
        int mins_ago = (n - 1 - i) * 5;
        int ht = 0 - (mins_ago * 10 / 60);

        if (scale10) {
            sprintf(buf, "[%d", ht);
            sprintfAppend(buf, ",%d]", val);
        } else {
            sprintf(buf, "[%d", ht);
            sprintfAppend(buf, ",%d]", val * 10);
        }
        if (i < n - 1) strcat(buf, ",");
        webSend(buf);
        if (i % 50 == 49) webFlush();
        i++;
    }
}

void WebPage() {
    char buf[128];

    // Load Google Charts library once
    webSend("<script src=\"https://www.gstatic.com/charts/loader.js\"></script>");
    webSend("<script>google.charts.load('current',{packages:['corechart']});</script>");
    webFlush();

    // Chart configs: id, title, unit, color, array, scale10
    // We emit 6 chart divs, then one script block that draws all 6

    // Chart containers
    webSend("<div id=\"c0\" style=\"width:100%;height:250px;\"></div>");
    webSend("<div id=\"c1\" style=\"width:100%;height:250px;\"></div>");
    webSend("<div id=\"c2\" style=\"width:100%;height:250px;\"></div>");
    webSend("<div id=\"c3\" style=\"width:100%;height:250px;\"></div>");
    webSend("<div id=\"c4\" style=\"width:100%;height:250px;\"></div>");
    webSend("<div id=\"c5\" style=\"width:100%;height:250px;\"></div>");
    webFlush();

    if (h_count < 2) {
        webSend("<p>Collecting data... Charts appear after 2 samples.</p>");
        return;
    }

    // Start script block
    webSend("<script>");
    webSend("google.charts.setOnLoadCallback(function(){");

    // Helper JS function to draw a chart from data
    webSend("function dc(id,t,u,c,d){");
    webSend("var dt=new google.visualization.DataTable();");
    webSend("dt.addColumn('number','Hours');");
    webSend("dt.addColumn('number',u);");
    webSend("dt.addRows(d.map(function(r){return[r[0]/10,r[1]/10];}));");
    webSend("var o={title:t,legend:'none',curveType:'none',");
    webSend("hAxis:{title:'Hours',direction:1},");
    webSend("vAxis:{title:u},");
    webSend("colors:[c],lineWidth:1,pointSize:0,");
    webSend("chartArea:{width:'80%',height:'65%'}};");
    webSend("new google.visualization.LineChart(");
    webSend("document.getElementById(id)).draw(dt,o);}");
    webFlush();

    // Chart 0: Temperature (×10 values)
    webSend("dc('c0','Temperature (24h)','\\u00b0C','#e74c3c',[");
    emit_chart(0, 1);
    webSend("]);");
    webFlush();

    // Chart 1: Humidity (raw %)
    webSend("dc('c1','Humidity (24h)','%','#3498db',[");
    emit_chart(1, 0);
    webSend("]);");
    webFlush();

    // Chart 2: Wind Average (×10 values)
    webSend("dc('c2','Wind Average (24h)','m/s','#27ae60',[");
    emit_chart(2, 1);
    webSend("]);");
    webFlush();

    // Chart 3: Rain (×10 values)
    webSend("dc('c3','Rain (24h)','mm','#2980b9',[");
    emit_chart(3, 1);
    webSend("]);");
    webFlush();

    // Chart 4: Brightness (×10 values)
    webSend("dc('c4','Brightness (24h)','lux','#f39c12',[");
    emit_chart(4, 1);
    webSend("]);");
    webFlush();

    // Chart 5: UV Index (×10 values)
    webSend("dc('c5','UV Index (24h)','UVI','#9b59b6',[");
    emit_chart(5, 1);
    webSend("]);");
    webFlush();

    webSend("});");
    webSend("</script>");
    webFlush();
}

void WebCall() {
    char out[80];
    if (br_ok) {
        sprintf(out, "{s}Bresser ID{m}0x%04X{e}", br_id);
        webSend(out);
        sprintf(out, "{s}Temperature{m}%.1f C{e}", br_temp);
        webSend(out);
        sprintf(out, "{s}Humidity{m}%d %%{e}", br_hum);
        webSend(out);
        sprintf(out, "{s}Wind Avg{m}%.1f m/s{e}", br_wind_avg);
        webSend(out);
        sprintf(out, "{s}Rain{m}%.1f mm{e}", br_rain);
        webSend(out);
        sprintf(out, "{s}Brightness{m}%.1f lux{e}", br_lux);
        webSend(out);
        sprintf(out, "{s}UV Index{m}%.1f{e}", br_uvi);
        webSend(out);
        sprintf(out, "{s}RSSI{m}%.0f dBm{e}", br_rssi);
        webSend(out);
        if (br_batt) { webSend("{s}Battery{m}OK{e}"); }
        else { webSend("{s}Battery{m}Low{e}"); }
        sprintf(out, "{s}Packets{m}%d{e}", br_cnt);
        webSend(out);
        sprintf(out, "{s}Chart{m}%d / 288 pts{e}", h_count);
        webSend(out);
    } else {
        webSend("{s}Bresser{m}waiting for data{e}");
    }
    if (soil_ok) {
        sprintf(out, "{s}Soil ID{m}0x%04X{e}", soil_id);
        webSend(out);
        sprintf(out, "{s}Soil Temp{m}%.1f C{e}", soil_temp);
        webSend(out);
        sprintf(out, "{s}Soil Moisture{m}%d %%{e}", soil_moisture);
        webSend(out);
    }
}

void JsonCall() {
    char out[80];
    if (br_ok) {
        sprintf(out, ",\"Bresser\":{\"ID\":\"%04X\"", br_id);
        responseAppend(out);
        sprintf(out, ",\"Temp\":%.1f", br_temp);
        responseAppend(out);
        sprintf(out, ",\"Hum\":%d", br_hum);
        responseAppend(out);
        sprintf(out, ",\"WindAvg\":%.1f", br_wind_avg);
        responseAppend(out);
        sprintf(out, ",\"Rain\":%.1f", br_rain);
