        responseAppend(out);
        sprintf(out, ",\"Cnt\":%d}", soil_cnt);
        responseAppend(out);
    }
}

int main() {
    spiInit(-1, -1, -1, SPI_MHZ);
    gpioInit(GDO0_PIN, 0);
    gpioInit(CS_PIN, 1);
    cc_reset();
    spiSetCS(1, CS_PIN);

    int ver = cc_read_status(0x31);
    char buf[64];
    sprintf(buf, "CC1101 version: 0x%02X\n", ver);
    printString(buf);

    if (ver == 0 || ver == 0xFF) {
        printStr("ERROR: CC1101 not found\n");
        return 1;
    }

    if (!cc_init_bresser()) {
        printStr("ERROR: CC1101 init failed\n");
        return 1;
    }

    // Init all state
    br_ok = 0;
    br_cnt = 0;
    soil_ok = 0;
    soil_cnt = 0;
    h_pos = 0;
    h_count = 0;
    sec_cnt = 0;

    // Zero ring buffers
    int i;
    for (i = 0; i < NPTS; i++) {
        h_temp[i] = 0;
        h_hum[i] = 0;
        h_wavg[i] = 0;
        h_rain[i] = 0;
        h_lux[i] = 0;
        h_uvi[i] = 0;
    }

    printStr("Bresser CC1101 + 24h charts ready\n");
    printStr("Charts: 6 variables, 288 pts each (5-min interval)\n");
    return 0;
}
